source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json, glob, os

for model, path in [('Qwen', '/root/autodl-tmp/ctrl_contam_pilot/results'),
                     ('Llama', '/root/autodl-tmp/ctrl_contam_llama/results'),
                     ('Mistral', '/root/autodl-tmp/ctrl_contam_mistral/results')]:
    print(f'=== {model} ===')
    files = sorted(glob.glob(os.path.join(path, '*_results.json')))
    for f in files:
        try:
            d = json.load(open(f))
            acc = d.get('accuracy', d.get('acc', d.get('eval_accuracy', None)))
            if acc is None:
                # try nested
                for k,v in d.items():
                    if isinstance(v, dict) and ('accuracy' in v or 'acc' in v):
                        acc = v.get('accuracy', v.get('acc'))
                        break
            print(f'  {os.path.basename(f)}: {acc}')
        except Exception as e:
            print(f'  {os.path.basename(f)}: ERROR {e}')
"
